const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={dashboard:'/dashboard',results:'/dashboard/results',bankrolls:'/dashboard/bankrolls',simulate:'/dashboard/simulate',tutorial:'/dashboard/training/tutorial',charts:'/dashboard/training/charts',basic:'/dashboard/training/basic',count:'/dashboard/training/count',deviation:'/dashboard/training/deviation',decks:'/dashboard/training/decks','true-count':'/dashboard/training/true-count',checkout:'/dashboard/training/checkouts',career:'/dashboard/career',directory:'/dashboard/game-directory',forum:'/dashboard/forum',messages:'/dashboard/messages',settings:'/dashboard/settings'};
const names={dashboard:'Dashboard',results:'Results Tracker',bankrolls:'Bankrolls',simulate:'Monte Carlo Simulator',tutorial:'Interactive Tutorial',charts:'Strategy Charts',basic:'Basic Strategy',count:'Counting Drills',deviation:'Deviations',decks:'Deck Estimation','true-count':'True Count Conversion',checkout:'Checkouts',career:'Career Mode',directory:'Game Directory',forum:'Private Forum',messages:'Messages',settings:'Account Settings'};
const iconPaths={chart:'M3 3v18h18 M6 15l4-5 4 3 6-8',book:'M12 5v16 M3 4h5q4 0 4 3q0-3 4-3h5v15h-5q-4 0-4 2q0-2-4-2H3Z',brain:'M9 4a3 3 0 0 0-5 3a4 4 0 0 0-1 7a4 4 0 0 0 6 5 M15 4a3 3 0 0 1 5 3a4 4 0 0 1 1 7a4 4 0 0 1-6 5 M9 3v18 M15 3v18 M5 10h4 M15 14h4',calc:'M6 2h12v20H6Z M9 6h6 M9 10h1 M14 10h1 M9 14h1 M14 14h1 M9 18h1 M14 18h1',pin:'M19 10c0 6-7 11-7 11S5 16 5 10a7 7 0 1 1 14 0Z M15 10a3 3 0 1 1-6 0a3 3 0 1 1 6 0',chat:'M3 3h18v14H8l-5 4Z',cards:'M7 4h13v17H7Z M4 18L2 4l10-2 M11 9l3-3 3 3-3 3Z',users:'M16 21v-3a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v3 M13 6a4 4 0 1 1-8 0a4 4 0 1 1 8 0 M17 3a4 4 0 0 1 0 8 M19 14q3 1 3 5',trophy:'M7 3h10v8q0 5-5 5q-5 0-5-5Z M7 5H3v4q0 4 4 4 M17 5h4v4q0 4-4 4 M12 16v5 M8 21h8',home:'M3 10l9-8 9 8 M5 9v12h14V9 M9 21v-8h6v8',wallet:'M3 5h17v16H3Z M3 5V3h15v2 M15 11h6v5h-6Z',settings:'M12 8a4 4 0 1 0 0 8a4 4 0 1 0 0-8 M10 2h4l1 4 4-1 2 4-3 3 3 3-2 4-4-1-1 4h-4l-1-4-4 1-2-4 3-3-3-3 2-4 4 1Z',arrow:'M4 12h16 M14 6l6 6-6 6',menu:'M3 6h18 M3 12h18 M3 18h18',plus:'M12 4v16 M4 12h16',download:'M12 3v12 M7 10l5 5 5-5 M4 16v5h16v-5',clock:'M12 3a9 9 0 1 0 0 18a9 9 0 1 0 0-18 M12 7v6l4 2',check:'M4 12l5 5L20 6',close:'M6 6l12 12 M6 18L18 6',eye:'M2 12q10-15 20 0q-10 15-20 0 M12 8a4 4 0 1 0 0 8a4 4 0 1 0 0-8'};
function icon(name='chart'){return `<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${iconPaths[name]||iconPaths.chart}"/></svg>`;}
const brand=()=>`<a href="/" class="brand"><img src="/logo.svg" alt="">Felt & Fortune</a>`;
const link=(key,label,cls='')=>`<a class="${cls}" href="${paths[key]}">${label||names[key]}</a>`;
let requestController=new AbortController();
let user=null,configInfo={},routeVersion=0,cleanup=()=>{},cleanupNav=()=>{},activeBankroll=localStorage.getItem('activeBankroll')||'',toastTimer;
async function api(path,method='GET',data){const res=await fetch(path,{method,signal:requestController.signal,headers:method==='GET'?{}:{'Content-Type':'application/json'},body:method==='GET'?undefined:JSON.stringify(data||{})});const body=await res.json();if(res.status===401&&user){user=null;go('/auth/login');}if(!res.ok)throw new Error(body.error||'Request failed.');return body;}
function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',4500);}
const money=(n,currency='USD')=>new Intl.NumberFormat('en-US',{style:'currency',currency,maximumFractionDigits:2}).format(Number(n)||0);
const number=(n,d=1)=>new Intl.NumberFormat('en-US',{maximumFractionDigits:d}).format(n);
const empty=(title,text,action='')=>`<div class="empty">${icon('chart')}<h3>${title}</h3><p>${text}</p>${action}</div>`;
const button=(text,id,cls='primary')=>`<button class="${cls}" id="${id}">${text}</button>`;
function field(name,label,value='',type='text',extra=''){return `<div class="field"><label for="${name}">${label}</label><input id="${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra}></div>`;}
function select(name,label,options,value){return `<div class="field"><label for="${name}">${label}</label><select name="${name}" id="${name}">${options.map(o=>{const [v,l]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(l)}</option>`;}).join('')}</select></div>`;}
const textarea=(name,label,value='',extra='')=>`<div class="field"><label for="${name}">${label}</label><textarea id="${name}" name="${name}" ${extra}>${esc(value)}</textarea></div>`;
const formData=form=>Object.fromEntries(new FormData(form));
function modal(title,body,onSubmit){const el=$('#modal');el.innerHTML=`<div class="modal-head"><h2>${title}</h2><button type="button" class="ghost" data-close aria-label="Close dialog">${icon('close')}</button></div><form id="modal-form">${body}<p class="form-error" role="alert"></p><div class="modal-actions"><button type="button" data-close>Cancel</button><button class="primary" type="submit">Save</button></div></form>`;$$('[data-close]',el).forEach(b=>b.onclick=()=>el.close());$('#modal-form').onsubmit=async e=>{e.preventDefault();const b=$('button[type=submit]',e.target);b.disabled=true;try{await onSubmit(formData(e.target));el.close();}catch(error){$('.form-error',el).textContent=error.message;}finally{b.disabled=false;}};el.showModal();}
function download(filename,text,type='text/csv'){const a=document.createElement('a');const url=URL.createObjectURL(new Blob([text],{type}));a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function csv(rows){return rows.map(row=>row.map(x=>{let s=String(x??'');if(/^[=+@]/.test(s)||/^-\D/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';}).join(',')).join('\r\n');}
function parseCSV(text){const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){let ch=text[i];if(ch==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++;}else quoted=!quoted;}else if(ch===','&&!quoted){row.push(cell);cell='';}else if((ch==='\n'||ch==='\r')&&!quoted){if(ch==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(Boolean))rows.push(row);row=[];cell='';}else cell+=ch;}if(quoted)throw new Error('Unclosed quote in CSV.');row.push(cell);if(row.some(Boolean))rows.push(row);return rows;}
function chart(series,{labels=['Actual','EV'],height=240}={}){if(!series[0]?.length||(series[0].length===1&&series[0][0][0]===0))return empty('Your chart starts here','Add a session to see your results over time.');const all=series.flat().map(p=>p[1]);let min=Math.min(0,...all),max=Math.max(1,...all),range=max-min;const maxX=Math.max(1,...series.flat().map(p=>p[0]));const x=n=>45+n/maxX*695,y=n=>height-22-(n-min)/range*(height-45);const lines=[0,1,2,3,4].map(i=>{const value=min+range*i/4;return `<line x1="45" x2="750" y1="${y(value)}" y2="${y(value)}" stroke="#cabb9e" stroke-dasharray="3 5"/><text x="37" y="${y(value)+4}" text-anchor="end" fill="#73604e" font-size="10">${number(value,0)}</text>`;}).join('');return `<svg class="chart" viewBox="0 0 760 ${height}" role="img" aria-label="${esc(labels.join(' and '))} chart">${lines}${series.map((s,i)=>`<polyline points="${s.map(p=>`${x(p[0])},${y(p[1])}`).join(' ')}" fill="none" stroke="${i?'#69734a':'#a54c2d'}" stroke-width="2.5" ${i?'stroke-dasharray="5 4"':''}/>`).join('')}</svg><div class="chart-labels"><span>0</span><span>${number(maxX)} ${labels[0]==='Profit path'?'rounds':'hours'}</span></div><div class="legend">${labels.map((l,i)=>`<span><i style="background:${i?'#69734a':'#a54c2d'}"></i>${esc(l)}</span>`).join('')}</div>`;}
function card(c,i=0,back=false){if(back)return '<span class="playing-card back" aria-label="Face-down card"></span>';let rank=c===1?'A':c===11?'J':c===12?'Q':c===13?'K':c;let suit=['♠','♦','♣','♥'][i%4];return `<span class="playing-card ${i%2?'red':''}" aria-label="${rank} ${['spades','diamonds','clubs','hearts'][i%4]}"><b>${rank}<br>${suit}</b>${c>=11?'♛':suit}<b>${rank}<br>${suit}</b></span>`;}
function tray(q=10){return `<div class="deck-tray" role="img" aria-label="Discard tray with cards to estimate"><div class="tray-back"></div><div class="stack" style="height:${q/24*126}px"></div><div class="tray-front"></div></div>`;}
function navbar(home=false){return `<nav class="topnav" aria-label="Main navigation">${brand()}${home?'<div class="navlinks">'+[['training','Training'],['tools','Tools'],['results','Results Tracker'],['community','Community'],['pricing','Free Access']].map(([id,l])=>`<a href="/#${id}">${l}</a>`).join('')+'</div>':''}<div class="nav-actions"><a class="button ghost small login-link" href="${user?paths.dashboard:'/auth/login'}">${user?'Dashboard':'Log In'}</a><a class="button primary small" href="${user?paths.dashboard:'/auth/signup'}">${user?'Open Workspace':'Get Started Free'}</a>${home?`<button class="menu-button ghost" id="nav-menu" aria-label="Toggle navigation" aria-expanded="false">${icon('menu')}</button>`:''}</div></nav>`;}
function footer(){const groups=[['Results & Tools',['results','simulate']],['Training',['basic','count','deviation','career']],['Community',['directory','forum','messages']]];return `<footer class="footer"><div class="footer-grid"><div>${brand()}<p class="mt">Training and tools for advantage players.<br>Every feature. Free forever.</p></div>${groups.map(([title,links])=>`<div><h4>${title}</h4>${links.map(k=>link(k)).join('')}</div>`).join('')}<div><h4>Company</h4><a href="/about">About</a><a href="/privacy">Privacy Policy</a><a href="/terms">Terms of Use</a></div></div><div class="copyright">© 2026 Felt & Fortune. Free blackjack training and analysis.</div></footer>`;}

function toolTiles(compact=false){return `<div class="tool-grid ${compact?'compact-tools':''}">${[['basic','brain','Practice','Build better decisions.'],['simulate','calc','Explore','Put your assumptions to the test.'],['results','chart','Reflect','See the story of your sessions.'],['tutorial','book','Learn','Start with the fundamentals.']].map(([k,i,t,d])=>`<a href="${paths[k]}" class="tool-tile">${icon(i)}<span class="tile-arrow" aria-hidden="true">↗</span><strong>${t}</strong><small>${d}</small></a>`).join('')}</div>`;}
function localDate(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}

function sectionHead(tag,title,text){return `<div class="section-header"><span class="eyebrow">${tag}</span><h2>${title}</h2>${text?`<p>${text}</p>`:''}</div>`;}
function feature(title,text,ic='brain',key){return `<${key?'a':'div'} ${key?`href="${paths[key]}"`:''} class="panel feature">${icon(ic)}<h3>${title}</h3><p>${text}</p></${key?'a':'div'}>`;}
function homepage(){const training=[['Interactive Tutorial','Learn the foundations, one guided lesson at a time.','book','tutorial'],['Charts','Study H17 and S17 basic strategy and Hi-Lo indices.','cards','charts'],['Basic Strategy','Build accuracy through hands-on practice and feedback.','brain','basic'],['Counting Drills','Sharpen your running count with timed card sequences.','calc','count'],['Deviations','Practice decisions that change with the true count.','chart','deviation'],['Deck Estimation','Practice estimating the cards in a discard tray.','cards','decks'],['Checkouts','Combine your skills in a mixed practice assessment.','check','checkout'],['Career Mode','Earn points from verified exercises and compare progress.','trophy','career']];
$('#app').innerHTML=navbar(true)+`<main id="main" class="landing"><section class="hero"><div class="hero-layout"><div class="hero-copy"><div class="hero-kicker">A little practice. A clearer picture.</div><h1>Know your cards.<span>Find your rhythm.</span></h1><p class="lead">Your place to learn blackjack, sharpen your decisions, and understand the numbers behind every session. A full set of tools, free for everyone.</p><div class="hero-actions"><a class="button primary large" href="${user?paths.dashboard:'/auth/signup'}">${user?'Open your workspace':'Find your starting hand'} ${icon('arrow')}</a><a class="button ghost" href="/#training">Try a drill ↓</a></div><p class="byline">No subscription. No trial clock. Just room to improve.</p></div><figure class="hero-art"><img src="/felt-and-fortune-cover.png" alt="Vintage playing cards on olive felt" fetchpriority="high"><figcaption><span>FELT & FORTUNE</span><span>GOOD HABITS START HERE.</span></figcaption></figure></div><div class="hero-strip"><span>Always free to explore</span><span>Learn · Practice · Model · Reflect</span><span>Made for the curious player</span></div></section><section class="section tool-collection"><div class="container"><div class="collection-head"><h2>Make yourself at home.</h2><p>Choose a tool. Build a habit.</p></div>${toolTiles()}</div></section><section class="section" id="training"><div class="container">${sectionHead('♧ Complete Blackjack Training','Build Your Skills, Hand by Hand','Interactive lessons, targeted drills, strategy charts, and assessments for your practice routine.')}<div class="grid two training-previews"><div class="panel practice-preview" id="demo-basic"><h3>${icon('brain')} Basic Strategy</h3><div class="table-label">Dealer</div><div class="cards">${card(11)}${card(0,0,true)}</div><div class="table-label">Your hand (soft 18)</div><div class="cards">${card(1)}${card(7,1)}</div><div class="actions">${['Hit','Stand','Double','Split'].map((s,i)=>`<button class="${i<3?'primary':''}" data-demo-answer="${s}" ${i===3?'disabled':''}>${s}</button>`).join('')}</div><div class="feedback" aria-live="polite"></div></div><div class="panel practice-preview" id="demo-count"><h3>${icon('calc')} Counting Drill <span class="badge" style="margin-left:auto">Hi-Lo</span></h3><div class="table-label">Cards dealt</div><div class="cards compact mt">${[1,4,7,7,7].map((c,i)=>card(c,i)).join('')}</div><p class="mt" style="text-align:center">What is the running count?</p><form class="inline-answer"><input type="number" aria-label="Running count" placeholder="?" required><button class="primary">Check</button></form><div class="feedback" aria-live="polite"></div></div><div class="panel practice-preview" id="demo-decks"><h3>${icon('cards')} Deck Estimation</h3><div class="table-label">Discard tray</div>${tray(10)}<form class="inline-answer"><input type="number" step=".25" aria-label="Estimated decks" placeholder="?" required><button class="primary">Check</button></form><div class="feedback" aria-live="polite"></div></div><div class="panel practice-preview" id="demo-deviation"><h3>${icon('chart')} Deviations <span class="badge" style="margin-left:auto">TC +6</span></h3><div class="table-label">Dealer</div><div class="cards">${card(6)}</div><div class="table-label">Your hand (20)</div><div class="cards">${card(12)}${card(12,1)}</div><div class="actions">${['Hit','Stand','Double','Split'].map(s=>`<button class="primary" data-demo-answer="${s}">${s}</button>`).join('')}</div><div class="feedback" aria-live="polite"></div></div></div><div class="grid four mt">${training.map(x=>feature(...x)).join('')}</div></div></section><section class="section" id="tools"><div class="container">${sectionHead('Simulation & Analysis','Explore the Numbers Behind Your Play','Configure your bankroll, rules, and bet spread. Run a simulation to understand expected results and the range of possible outcomes.')}<div class="showcase"><div class="browser-bar"><span class="browser-dots">•••</span>feltandfortune / simulate</div><div class="showcase-body"><div class="metric-grid">${[['Expected value','—','per hour'],['Standard deviation','—','per √hour'],['Risk of ruin','—','estimated'],['Hours to N₀','—','hours']].map(([l,v,s])=>`<div class="metric"><span class="label">${l}</span><span class="value" style="color:var(--blue)">${v}</span><small>${s}</small></div>`).join('')}</div><div class="grid three mt">${feature('Bankroll settings','Set your starting bankroll, unit amount, and rounds per hour.','wallet','simulate')}${feature('Table rules','Choose decks, penetration, payouts, and supported playing rules.','cards','simulate')}${feature('Bet spread','Set one or two hands and the wager at each count.','chart','simulate')}</div><p class="muted" style="text-align:center;margin:22px 0 0">Your inputs. Simulated hands. Calculated results.</p></div></div><div class="mt">${feature('Monte Carlo Simulator','Estimate hourly EV, volatility, and risk of ruin, then simulate up to a million rounds, inspect the bankroll path, and export your results.','chart','simulate')}</div></div></section><section class="section" id="results"><div class="container">${sectionHead('Professional Results Tracking','Every Game. One Clear Picture.','Log your sessions, compare profit with EV, and organize personal or shared bankrolls.')}<div class="showcase"><div class="browser-bar"><span class="browser-dots">•••</span>feltandfortune / dashboard</div><div class="showcase-body"><h3>Dashboard</h3>${chart([[[0,0],[4,180],[9,-300],[12,600],[17,850],[24,720],[30,1400],[36,1000],[42,2200],[50,2500]],[[0,0],[50,2000]]])}<p class="field-hint" style="text-align:center">Illustrative chart — not real player results.</p><div class="metric-grid">${[['Total profit','$0.00'],['Sessions','0'],['Hours','0.0 h'],['Avg / hour','$0.00']].map(([l,v])=>`<div class="metric"><span class="label">${l}</span><span class="value">${v}</span></div>`).join('')}</div></div></div><div class="grid three mt">${feature('Solo Bankrolls','Keep your own sessions and results private.','wallet','bankrolls')}${feature('Team Bankrolls','Share access, manage contributions, and allocate profit splits.','users','bankrolls')}${feature('Easy Import','Bring your session history with you using CSV import.','download','results')}</div></div></section><section class="section" id="community"><div class="container">${sectionHead('Community & Intel','Find Your Community','Exchange ideas, share observations, and keep in touch with other players.')}<div class="grid two">${feature('Private Forum','Discuss strategy, write trip reports, and connect through private messages.','chat','forum')}${feature('Game Directory','Browse player-submitted rules, penetration, heat reports, and reviews.','pin','directory')}</div></div></section><section class="section" id="pricing"><div class="container">${sectionHead('Free Access','Everything Included. Free Forever.','Every tool and every feature is available without payment.')}<div class="panel price-card"><div style="text-align:center"><span class="badge green">Free forever</span></div><h3>Felt & Fortune</h3><div class="price">$0<span> / forever</span></div><p class="sub">No card required. No expiration.</p>${[['Tools & Training',['Strategy charts','Training drills','Checkouts','Career Mode','Monte Carlo Simulator']],['Results Tracking',['Unlimited bankrolls','Team bankroll sharing','Friend bankrolls','Multi-game support','Data import','Analytics']],['Community',['Private forum','Game directory','Private messaging','Shared knowledge']]].map(([t,items])=>`<h4>${t.toUpperCase()}</h4><ul>${items.map(i=>`<li>${i}</li>`).join('')}</ul>`).join('')}<a href="/auth/signup" class="button primary">Create Your Free Account ${icon('arrow')}</a><p class="field-hint" style="text-align:center;margin:15px 0 0">All features remain free after you sign up.</p></div></div></section><section class="section" id="faq"><div class="container">${sectionHead('','Frequently Asked Questions','A few things to know before getting started.')}<div class="faq">${[['Is everything really free?','Yes. There are no subscriptions, trial periods, payment forms, or paid feature gates.'],['Which counting system is supported?','The training drills use Hi-Lo. Cards 2–6 count as +1, 7–9 as 0, and tens and aces as −1.'],['What can I track?','Track blackjack, poker, sports betting, or your own game types. Sessions support time, profit, EV, location, trip, notes, and custom fields.'],['How do team bankrolls work?','A bankroll owner adds existing users as editors or viewers. Editors can log sessions, while owners manage access and profit shares.'],['Can I import my existing results?','Yes. Download the CSV template from Results Tracker, map your historical data to its columns, and preview the import before saving.'],['Can I use this on my phone?','Yes. The interface adapts to phones, tablets, and desktop screens.'],['Will I be charged later?','No. This implementation has no billing system and no time-limited access.'],['Who can see my data?','Personal bankrolls are visible only to their owner. Shared bankrolls are visible to their members. Forum and directory contributions are visible to signed-in users.']].map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}</div></div></section></main>`+footer();
$('#nav-menu').onclick=()=>{const open=$('.navlinks').classList.toggle('open');$('#nav-menu').setAttribute('aria-expanded',open);};
for(const [id,answer] of [['demo-basic','Hit'],['demo-deviation','Split']])$$('[data-demo-answer]',$('#'+id)).forEach(b=>b.onclick=()=>{const f=$('.feedback',$('#'+id));const ok=b.dataset.demoAnswer===answer;f.className='feedback '+(ok?'positive':'negative');f.textContent=ok?'Correct. Nice work!':`The correct play is ${answer.toLowerCase()}.`;});
for(const [id,answer] of [['demo-count',0],['demo-decks',2.5]])$('form',$('#'+id)).onsubmit=e=>{e.preventDefault();const ok=Number($('input',e.target).value)===answer;const f=$('.feedback',$('#'+id));f.className='feedback '+(ok?'positive':'negative');f.textContent=ok?'Correct. Nice work!':`The answer is ${answer}.`;};}

function authPage(mode){const signup=mode==='signup',forgot=mode==='forgot-password',reset=mode==='reset-password';const title=signup?'Create Your Free Account':forgot?'Reset Your Password':reset?'Choose a New Password':'Sign In to Your Account';$('#app').innerHTML=`<main id="main" class="auth-page"><div class="auth-wrap"><div class="auth-box"><div class="auth-top"><a href="/" class="back muted" aria-label="Back to home">←</a>${brand()}</div>${signup?'<p style="text-align:center"><span class="badge green">Free forever</span></p>':''}<h1>${title}</h1><form id="auth-form">${signup?field('username','Username','','text','required minlength="3" maxlength="30" autocomplete="username" placeholder="Choose a username"'):''}${!reset?field('email','Email Address','','email','required autocomplete="email" placeholder="you@example.com"'):''}${!forgot?`<div class="field"><div class="field-head"><label for="password">Password</label>${!signup&&!reset?'<a href="/auth/forgot-password">Forgot password?</a>':''}</div><div class="password-wrap"><input name="password" id="password" type="password" required ${signup||reset?'minlength="10"':''} maxlength="256" autocomplete="${signup||reset?'new-password':'current-password'}" placeholder="${signup||reset?'At least 10 characters':'••••••••'}"><button type="button" class="show-password" aria-label="Show password">${icon('eye')}</button></div></div>${signup||reset?field('confirm','Confirm Password','','password','required minlength="10" autocomplete="new-password"'):''}`:''}${signup?'<label class="check-label field"><input name="terms" type="checkbox" required><span>I agree to the <a href="/terms">Terms of Use</a> and <a href="/privacy">Privacy Policy</a>.</span></label>':''}<p class="form-error" role="alert"></p><button class="primary" type="submit">${signup?'Create Account':forgot?'Send Reset Link':reset?'Save New Password':'Sign In'} ${icon('arrow')}</button></form><p class="auth-foot">${signup?'Already have an account? <a href="/auth/login">Sign in</a>':forgot||reset?'<a href="/auth/login">Back to sign in</a>':'Don’t have an account? <a href="/auth/signup">Create one free</a>'}</p></div><div class="auth-legal"><a href="/terms">Terms of Use</a> · <a href="/privacy">Privacy Policy</a></div></div></main>`;$('.show-password')?.addEventListener('click',e=>{const p=$('#password');p.type=p.type==='password'?'text':'password';e.currentTarget.setAttribute('aria-label',p.type==='text'?'Hide password':'Show password');});$('#auth-form').onsubmit=async e=>{e.preventDefault();const f=e.target;$('.form-error',f).textContent='';const data=formData(f);if((signup||reset)&&data.password!==data.confirm){$('.form-error',f).textContent='Passwords do not match.';return;}const b=$('button[type=submit]',f);b.disabled=true;try{if(reset)data.token=new URLSearchParams(location.search).get('token');const result=await api('/api/'+(mode==='login'?'login':mode),'POST',data);if(forgot){f.innerHTML='<div class="notice">If an account matches that email, a reset link has been sent.</div>';return;}if(reset){toast('Password updated. Please sign in.');go('/auth/login');return;}user=result.user;const next=sessionStorage.getItem('after-login');sessionStorage.removeItem('after-login');go(Object.values(paths).includes(next)?next:paths.dashboard);}catch(error){$('.form-error',f).textContent=error.message;}finally{b.disabled=false;}};}

function shell(key){const groups=[['Overview',['dashboard','results','bankrolls']],['Tools',['simulate']],['Training',['tutorial','charts','basic','count','deviation','decks','true-count','checkout','career']],['Community',['directory','forum','messages']],['Account',['settings']]];const icons={dashboard:'home',results:'chart',bankrolls:'wallet',simulate:'calc',tutorial:'book',charts:'cards',basic:'brain',count:'calc',deviation:'chart',decks:'cards','true-count':'calc',checkout:'check',career:'trophy',directory:'pin',forum:'chat',messages:'chat',settings:'settings'};$('#app').innerHTML=`<div class="shell"><aside class="sidebar" id="workspace-navigation">${brand()}<button class="ghost side-dismiss" id="side-dismiss" aria-label="Close navigation">${icon('close')}</button><nav class="side-nav" aria-label="Workspace navigation">${groups.map(([title,keys])=>`<div class="side-group">${title}</div>${keys.map(k=>`<a href="${paths[k]}" class="side-link ${key===k?'active':''}" ${key===k?'aria-current="page"':''}>${icon(icons[k])}${names[k]}</a>`).join('')}`).join('')}</nav><div class="side-user"><span class="avatar">${esc(user.username[0].toUpperCase())}</span><div>${esc(user.username)}<br><small class="positive">Free forever</small></div><button class="ghost small" id="logout" aria-label="Sign out" style="margin-left:auto">↪</button></div></aside><button class="sidebar-shade" id="sidebar-shade" aria-label="Close navigation" tabindex="-1"></button><main id="main" class="app-main"><header class="app-top"><div class="flex"><button class="menu-button ghost" id="side-toggle" aria-label="Open navigation" aria-expanded="false" aria-controls="workspace-navigation">${icon('menu')}</button><div class="breadcrumb">Workspace <span> / ${names[key]||'Page'}</span></div></div><span class="badge green">All features unlocked</span></header><div id="page"><div class="loading"><span class="spinner"></span>Loading…</div></div></main></div>`;$('#logout').onclick=async()=>{await api('/api/logout','POST');user=null;go('/');};const toggleNav=open=>{$('.sidebar').classList.toggle('open',open);$('#side-toggle').setAttribute('aria-expanded',String(open));if(open)$('#side-dismiss').focus();else $('#side-toggle').focus();};$('#side-toggle').onclick=()=>toggleNav(!$('.sidebar').classList.contains('open'));$('#side-dismiss').onclick=()=>toggleNav(false);$('#sidebar-shade').onclick=()=>toggleNav(false);const closeNav=e=>{if(e.key==='Escape'&&$('.sidebar')?.classList.contains('open'))toggleNav(false);};document.addEventListener('keydown',closeNav);cleanupNav=()=>document.removeEventListener('keydown',closeNav);}
function head(title,desc,actions=''){return `<div class="page-head"><div><h1>${title}</h1><p>${desc}</p></div>${actions}</div>`;}
const records=async(kind,parent='')=>(await api(`/api/records?kind=${kind}${parent?'&parent='+encodeURIComponent(parent):''}`)).records;
async function saveRecord(kind,body,parent,id){return api('/api/records'+(id?'/'+id:''),id?'PATCH':'POST',{kind,body,parent});}
function errorView(error){$('#page').innerHTML=head('Something went wrong','Your data has not been changed.')+`<div class="notice">${esc(error.message)}</div><button id="retry">Try again</button>`;$('#retry').onclick=()=>render();}
async function resultsPage(key){let [bankrolls,sessions]=await Promise.all([records('bankroll'),records('session')]);if(!bankrolls.some(b=>b.id===activeBankroll)){activeBankroll=bankrolls[0]?.id||'';}let days='All',game='All',trip='';function paint(){const bank=bankrolls.find(b=>b.id===activeBankroll),cur=bank?.body.currency||'USD';let filtered=sessions.filter(s=>s.parent===activeBankroll&&(game==='All'||s.body.game===game)&&(!trip||s.body.trip===trip)&&(days==='All'||Date.parse(s.body.date)>=Date.now()-Number(days)*86400000)).sort((a,b)=>a.body.date.localeCompare(b.body.date));let profit=0,ev=0,hours=0;const actual=[[0,0]],expected=[[0,0]];filtered.forEach(s=>{profit+=s.body.profit;ev+=s.body.ev;hours+=s.body.hours;actual.push([hours,profit]);expected.push([hours,ev]);});$('#page').innerHTML=head(names[key],key==='dashboard'?'Your performance at a glance.':'Log, organize, and explore every session.',`<button class="primary" id="new-session">${icon('plus')} Add Session</button>`)+(key==='dashboard'?`<section class="dashboard-tools" aria-label="Quick tools"><h2>Your next good habit.</h2>${toolTiles(true)}</section>`:'')+`<div class="toolbar"><select id="bank-select" aria-label="Bankroll">${bankrolls.map(b=>`<option value="${b.id}" ${b.id===activeBankroll?'selected':''}>${esc(b.body.name)} · ${esc(b.body.currency)}</option>`).join('')}</select><select id="game-filter" aria-label="Filter game">${['All',...new Set(sessions.map(s=>s.body.game))].map(g=>`<option ${game===g?'selected':''}>${esc(g)}</option>`).join('')}</select><select id="trip-filter" aria-label="Filter trip"><option value="">All trips</option>${[...new Set(sessions.map(s=>s.body.trip).filter(Boolean))].map(g=>`<option ${trip===g?'selected':''}>${esc(g)}</option>`).join('')}</select><div class="spacer"></div><button id="import">Import CSV</button><button id="export">${icon('download')} Export</button><button class="ghost small" id="template">CSV template</button></div><div class="panel mb">${chart([actual,expected])}<div class="toolbar" style="justify-content:center;margin-bottom:0"><div class="tabs">${[['1','24H'],['7','7D'],['30','30D'],['90','90D'],['365','1Y'],['All','All']].map(([v,l])=>`<button data-days="${v}" class="${days===v?'active':''}">${l}</button>`).join('')}</div></div></div><div class="metric-grid mb">${[['Total Profit',money(profit,cur),profit>=0?'positive':'negative'],['Sessions',filtered.length,''],['Hours',number(hours)+' h',''],['Avg / Hour',money(hours?profit/hours:0,cur),'']].map(([l,v,cls])=>`<div class="metric"><span class="label">${l}</span><span class="value ${cls}">${v}</span></div>`).join('')}</div><div class="panel"><div class="flex between mb"><h3 style="margin:0">${key==='dashboard'?'Recent Sessions':'Sessions'}</h3><span class="muted">EV ${money(ev,cur)}</span></div>${filtered.length?`<div class="table-wrap"><table><thead><tr><th>Date</th><th>Game / Location</th><th>Hours</th><th>Profit</th><th>EV</th><th>Player</th><th></th></tr></thead><tbody>${filtered.slice().reverse().slice(0,key==='dashboard'?10:1000).map(s=>`<tr><td>${esc(s.body.date)}</td><td><strong>${esc(s.body.game)}</strong><br><small class="muted">${esc(s.body.location||'—')}</small></td><td>${number(s.body.hours)}</td><td class="${s.body.profit>=0?'positive':'negative'}">${money(s.body.profit,cur)}</td><td>${money(s.body.ev,cur)}</td><td>${esc(s.username)}</td><td><button class="small ghost" data-edit="${s.id}">View / Edit</button></td></tr>`).join('')}</tbody></table></div>`:empty('No sessions yet','Add your first session or import your existing results.')}<p class="field-hint">Figures use the selected bankroll’s currency. Different currencies are never combined.</p></div>`;
$('#bank-select').onchange=e=>{activeBankroll=e.target.value;localStorage.setItem('activeBankroll',activeBankroll);paint();};$('#game-filter').onchange=e=>{game=e.target.value;paint();};$('#trip-filter').onchange=e=>{trip=e.target.value;paint();};$$('[data-days]').forEach(b=>b.onclick=()=>{days=b.dataset.days;paint();});$('#new-session').onclick=()=>editSession();$$('[data-edit]').forEach(b=>b.onclick=()=>editSession(sessions.find(s=>s.id===b.dataset.edit)));
$('#export').onclick=()=>download('felt-and-fortune-sessions.csv',csv([['date','game','location','hours','profit','ev','notes','trip','fields'],...filtered.map(s=>['date','game','location','hours','profit','ev','notes','trip'].map(k=>s.body[k]).concat(JSON.stringify(s.body.fields||{})))]));$('#template').onclick=()=>download('session-template.csv',csv([['date','game','location','hours','profit','ev','notes','trip','fields'],['2026-01-01','Blackjack','Example venue',2,100,25,'Example only — replace before importing','Example trip','{}']]));$('#import').onclick=()=>importSessions();}
async function refresh(){sessions=await records('session');paint();}
function editSession(row){const b=row?.body||{date:localDate(),game:'Blackjack',hours:1,profit:0,ev:0};modal(row?'Session Details':'Add Session',`<div class="grid two">${field('date','Date',b.date,'date','required')}${field('game','Game',b.game,'text','required list="game-types"')}<datalist id="game-types"><option>Blackjack</option><option>Poker</option><option>Sports Betting</option></datalist>${field('location','Location',b.location)}${field('trip','Trip',b.trip)}${field('hours','Hours',b.hours,'number','required min="0" max="1000" step=".01"')}${field('profit','Profit / loss',b.profit,'number','required step=".01"')}${field('ev','Expected value',b.ev,'number','required step=".01"')}</div>${textarea('notes','Notes',b.notes)}${textarea('fields','Custom fields (JSON object)',JSON.stringify(b.fields||{}),'spellcheck="false"')}${row?`<button type="button" class="danger" id="delete-session">Delete Session</button>`:''}`,async data=>{let fields;try{fields=JSON.parse(data.fields);}catch{throw new Error('Custom fields must be a valid JSON object.');}if(!fields||Array.isArray(fields)||typeof fields!=='object')throw new Error('Custom fields must be an object.');await saveRecord('session',{...data,fields},row?.parent||activeBankroll,row?.id);await refresh();toast('Session saved.');});if(row)$('#delete-session').onclick=async()=>{if(!confirm('Delete this session? This cannot be undone.'))return;try{await api('/api/records/'+row.id,'DELETE');$('#modal').close();await refresh();toast('Session deleted.');}catch(e){$('.form-error',$('#modal')).textContent=e.message;}};}
function importSessions(){modal('Import Sessions',`<p>Import into the selected bankroll. Required columns: date, game, hours, profit, ev. Optional: location, notes, trip, fields.</p><div class="field"><label for="csv-file">CSV file</label><input type="file" id="csv-file" accept=".csv,text/csv" required></div><div id="csv-preview"></div>`,async()=>{if(!importRows.length)throw new Error('Select a valid CSV first.');let saved=0;try{for(const row of importRows){await saveRecord('session',row,activeBankroll);saved++;}}catch(e){importRows=importRows.slice(saved);await refresh();throw new Error(`${saved} saved; ${importRows.length} remain. ${e.message}`);}await refresh();toast(`${saved} sessions imported.`);});let importRows=[];$('#csv-file').onchange=async e=>{importRows=[];try{const file=e.target.files[0];if(file.size>2000000)throw new Error('Choose a file under 2 MB.');const rows=parseCSV(await file.text());const headers=rows.shift().map(h=>h.replace(/^\uFEFF/,'').trim().toLowerCase());for(const key of ['date','game','hours','profit','ev'])if(!headers.includes(key))throw new Error('Missing column: '+key);if(rows.length>1000)throw new Error('Import up to 1,000 sessions at a time.');importRows=rows.map((cells,index)=>{let body=Object.fromEntries(headers.map((h,i)=>[h,cells[i]||'']));for(const k of ['hours','profit','ev']){if(!body[k].trim()||!Number.isFinite(Number(body[k])))throw new Error(`Row ${index+2}: invalid ${k}.`);body[k]=Number(body[k]);}if(body.hours<0||body.hours>1000||!/^\d{4}-\d{2}-\d{2}$/.test(body.date)||!body.game)throw new Error(`Row ${index+2}: check date, game, and hours.`);body.fields=body.fields?JSON.parse(body.fields):{};return body;});$('#csv-preview').innerHTML=`<div class="notice">${importRows.length} sessions ready. Review the first five below, then save.</div><div class="table-wrap"><table><thead><tr><th>Date</th><th>Game</th><th>Profit</th></tr></thead><tbody>${importRows.slice(0,5).map(r=>`<tr><td>${esc(r.date)}</td><td>${esc(r.game)}</td><td>${esc(r.profit)}</td></tr>`).join('')}</tbody></table></div>`;}catch(error){importRows=[];$('#csv-preview').innerHTML=`<p class="form-error">${esc(error.message)}</p>`;}};}
paint();}

async function bankrollPage(){const banks=await records('bankroll');const sessions=await records('session');$('#page').innerHTML=head('Bankrolls','Manage your funds, collaborators, and profit shares.',button(icon('plus')+' New Bankroll','new-bank'))+`<div class="grid two">${banks.map(b=>{let profit=sessions.filter(s=>s.parent===b.id).reduce((t,s)=>t+s.body.profit,0);return `<div class="panel"><div class="flex between"><h3>${esc(b.body.name)}</h3><span class="badge">${esc(b.body.type)}</span></div><div class="metric"><span class="label">Session profit</span><span class="value ${profit>=0?'positive':'negative'}">${money(profit,b.body.currency)}</span></div><div class="toolbar"><button data-manage="${b.id}">Manage</button><button data-open-bank="${b.id}" class="primary">View Results</button></div></div>`;}).join('')}</div>`;$('#new-bank').onclick=()=>modal('New Bankroll',field('name','Bankroll name','','text','required')+select('type','Type',['solo','team','friends'],'solo')+select('currency','Currency',['USD','EUR','GBP','CAD','AUD'],'USD')+field('initial','Starting bankroll',0,'number','min="0" step=".01" required'),async data=>{await saveRecord('bankroll',data);await bankrollPage();toast('Bankroll created.');});$$('[data-open-bank]').forEach(b=>b.onclick=()=>{activeBankroll=b.dataset.openBank;localStorage.setItem('activeBankroll',activeBankroll);go(paths.results);});$$('[data-manage]').forEach(b=>b.onclick=()=>manage(banks.find(x=>x.id===b.dataset.manage)));
async function manage(bank){try{const [m,contributions]=await Promise.all([api('/api/members?bankroll='+bank.id),records('contribution',bank.id)]);const owner=m.members.some(x=>x.user_id===user.id&&x.role==='owner');const profit=sessions.filter(s=>s.parent===bank.id).reduce((t,s)=>t+s.body.profit,0);const balance=bank.body.initial+profit+contributions.reduce((t,r)=>t+r.body.amount,0);modal(esc(bank.body.name),`<div class="metric mb"><span class="label">Balance including contributions</span><span class="value">${money(balance,bank.body.currency)}</span></div><h3>Members & profit allocation</h3><div class="table-wrap mb"><table><thead><tr><th>Player</th><th>Role</th><th>Share</th><th>Profit allocation</th><th></th></tr></thead><tbody>${m.members.map(x=>`<tr><td>${esc(x.username)}</td><td>${x.role}</td><td>${x.share}%</td><td>${money(profit*x.share/100,bank.body.currency)}</td><td>${owner&&x.role!=='owner'?`<button type="button" class="ghost small" data-remove-member="${esc(x.username)}">Remove</button>`:''}</td></tr>`).join('')}</tbody></table></div>${owner?`<h3>Add or update a member</h3><div class="grid two">${field('username','Existing username')}${select('role','Permission',[['viewer','View only'],['editor','Log own sessions']],'viewer')}${field('share','Profit share (%)',0,'number','min="0" max="100" step=".01"')}</div><p class="field-hint">Adding a member gives them access to this bankroll. The owner keeps the unallocated share.</p><button type="button" id="add-member">Add / Update Member</button><hr style="border-color:var(--border);margin:25px 0">${field('name','Bankroll name',bank.body.name,'text','required')}${field('initial','Starting bankroll',bank.body.initial,'number','min="0" step=".01"')}`:''}<h3 class="mt">Contributions & withdrawals</h3>${contributions.length?contributions.map(r=>`<p>${esc(r.username)} · ${money(r.body.amount,bank.body.currency)}<br><small>${esc(r.body.note)}</small></p>`).join(''):'<p>No contributions yet.</p>'}<div class="grid two">${field('amount','Amount (negative for withdrawal)',0,'number','step=".01"')}${field('note','Note')}</div><button type="button" id="add-contribution">Record Contribution</button>`,async data=>{if(owner)await saveRecord('bankroll',{...bank.body,name:data.name,initial:data.initial},null,bank.id);await bankrollPage();});$('#add-member')?.addEventListener('click',async()=>{try{const d=formData($('#modal-form'));await api('/api/members','POST',{bankroll:bank.id,username:d.username,role:d.role,share:d.share});$('#modal').close();await manage(bank);toast('Member access updated.');}catch(e){$('.form-error',$('#modal')).textContent=e.message;}});$$('[data-remove-member]').forEach(b=>b.onclick=async()=>{try{await api('/api/members','DELETE',{bankroll:bank.id,username:b.dataset.removeMember});$('#modal').close();await manage(bank);}catch(e){$('.form-error',$('#modal')).textContent=e.message;}});$('#add-contribution').onclick=async()=>{try{const d=formData($('#modal-form'));await saveRecord('contribution',{amount:d.amount,note:d.note},bank.id);$('#modal').close();await manage(bank);toast('Contribution saved.');}catch(e){$('.form-error',$('#modal')).textContent=e.message;}};}catch(e){toast(e.message);}}
}

async function drillPage(mode){let challenge=null,h17=false,attempts=0,correct=0,streak=0,started=Date.now(),dealt=0,timer=null,pace=1000;const mixed=mode==='career'||mode==='checkout';const progress=await api('/api/progress');const prior=progress.progress.find(r=>r.mode===mode);$('#page').innerHTML=head(names[mode],mode==='career'?'Build your skills and earn a place on the shared leaderboard.':mode==='checkout'?'A 20-question assessment combining five training skills.':'Focused practice with immediate feedback and saved progress.')+`<div class="drill-stage"><div class="drill-settings"><div class="flex"><span class="badge">${mode==='deviation'?'Hi-Lo · S17':'Practice'}</span>${mode==='basic'||mixed?'<select id="drill-rule" aria-label="Dealer rule"><option value="false">Dealer stands on soft 17</option><option value="true">Dealer hits soft 17</option></select>':''}</div><span class="muted">Lifetime: ${prior?.correct||0} / ${prior?.attempts||0}</span></div><div class="panel mb"><div class="statline"><div><small class="muted">SESSION ACCURACY</small><strong id="accuracy">—</strong></div><div><small class="muted">CORRECT</small><strong id="correct-stat">0 / 0</strong></div><div><small class="muted">STREAK</small><strong id="streak">0</strong></div><div><small class="muted">TIME</small><strong id="elapsed">0:00</strong></div>${mode==='career'?'<div><small class="muted">SESSION POINTS</small><strong id="points">0</strong></div>':''}</div>${mode==='checkout'?'<div class="progress-track"><div id="checkout-progress" style="width:0"></div></div>':''}</div><div id="exercise" class="felt"></div><div class="notice">${mode==='deviation'?'Indices use common six-deck S17 Hi-Lo decisions with no surrender. Additional index sets remain planned.':mode==='decks'?'Estimate in quarter-deck increments. The tray uses an illustrative, uniformly scaled card stack; it is not a calibrated photograph.':mode==='true-count'?'True count = running count ÷ remaining decks. Round down toward negative infinity (for example, −3 ÷ 2 → −2).':'Basic strategy exercises use 4–8 decks, US peek, doubles on any two cards, double after split, and no surrender.'}</div>${mode==='career'?'<div class="panel mt"><h3>Leaderboard</h3><div id="leaderboard"></div></div>':''}</div>`;
let alive=true;const clock=setInterval(()=>{if(!$('#elapsed'))return;const t=Math.floor((Date.now()-started)/1000);$('#elapsed').textContent=`${Math.floor(t/60)}:${String(t%60).padStart(2,'0')}`;},1000);cleanup=()=>{alive=false;clearInterval(clock);clearInterval(timer);};$('#drill-rule')?.addEventListener('change',e=>{h17=e.target.value==='true';next();});
async function leaderboard(){const result=await api('/api/leaderboard');if(!alive)return;$('#leaderboard').innerHTML=result.players.length?`<div class="table-wrap"><table><thead><tr><th>Rank</th><th>Player</th><th>Points</th><th>Accuracy</th></tr></thead><tbody>${result.players.map((p,i)=>`<tr><td>${i+1}</td><td>${esc(p.username)}</td><td>${p.score}</td><td>${number(p.score/10/p.attempts*100)}%</td></tr>`).join('')}</tbody></table></div>`:empty('A fresh leaderboard','Complete a career exercise to record your first score.');}
async function next(){clearInterval(timer);if(mode==='checkout'&&attempts>=20){$('#exercise').innerHTML=`${icon('trophy')}<h2>Checkout Complete</h2><p>You answered ${correct} of 20 exercises correctly.</p><div class="metric"><span class="value ${correct>=18?'positive':''}">${Math.round(correct/20*100)}%</span></div><p class="mt">${correct>=18?'Strong practice result. Keep developing speed and consistency.':'Review the skills that need more practice and try again.'}</p><button id="restart-checkout" class="primary">Start Another Checkout</button>`;$('#restart-checkout').onclick=()=>drillPage(mode).catch(errorView);clearInterval(clock);return;}$('#exercise').innerHTML='<div class="loading"><span class="spinner"></span>Dealing…</div>';try{challenge=await api('/api/drill/new','POST',{mode,h17});if(!alive)return;paintExercise();}catch(e){$('#exercise').innerHTML=`<p class="form-error">${esc(e.message)}</p><button id="retry-drill">Retry</button>`;$('#retry-drill').onclick=next;}}
function paintExercise(){const q=challenge,ex=q.exercise;const handTotal=q.cards?.reduce((a,c)=>a+Math.min(c,10),0);const soft=q.cards?.includes(1)&&handTotal+10<=21;const t=handTotal+(soft?10:0);$('#exercise').innerHTML=`<div class="flex between"><span class="badge">${names[ex]||ex}</span>${q.tc!==undefined?`<span class="badge">True Count ${q.tc>=0?'+':''}${q.tc}</span>`:''}</div>${ex==='basic'||ex==='deviation'?`<div class="table-label">Dealer</div><div class="cards">${card(q.dealer)}${card(0,0,true)}</div><div class="table-label">Your hand (${soft?'soft ':''}${t})</div><div class="cards">${q.cards.map((c,i)=>card(c,i)).join('')}</div><div class="actions">${[['H','Hit'],['S','Stand'],['D','Double'],['P','Split']].map(([v,l])=>`<button class="primary" data-answer="${v}" ${v==='P'&&Math.min(q.cards[0],10)!==Math.min(q.cards[1],10)?'disabled':''}>${l}</button>`).join('')}</div>`:ex==='count'?`<div class="table-label mt">Keep a running count</div><div id="count-cards" class="cards" style="min-height:124px;margin:35px 0">${card(0,0,true)}</div><p id="count-position" class="muted">10 cards · Start when ready</p><div class="inline-answer"><select id="pace" aria-label="Card speed" style="max-width:150px"><option value="1500">1.5 seconds</option><option value="1000" selected>1 second</option><option value="500">0.5 seconds</option><option value="250">0.25 seconds</option></select><button id="start-count" class="primary">Start</button></div><form id="answer-form" class="inline-answer hidden"><input name="answer" type="number" placeholder="?" aria-label="Running count" required><button class="primary">Check</button></form>`:ex==='decks'?`<div class="table-label mt">How many decks are in the discard tray?</div>${tray(q.quarters)}<form id="answer-form" class="inline-answer"><input name="answer" type="number" step=".25" min="0" max="6" placeholder="?" aria-label="Estimated decks" required><button class="primary">Check</button></form>`:`<h2 class="mt">Convert to a True Count</h2><div class="grid two"><div class="metric"><span class="label">Running count</span><span class="value">${q.running}</span></div><div class="metric"><span class="label">Decks remaining</span><span class="value">${q.remaining}</span></div></div><form id="answer-form" class="inline-answer mt"><input name="answer" type="number" placeholder="?" aria-label="True count" required><button class="primary">Check</button></form>`}<div id="drill-feedback" class="feedback" aria-live="polite"></div><div id="next-wrap"></div>`;$$('[data-answer]').forEach(b=>b.onclick=()=>answer(b.dataset.answer));$('#answer-form')?.addEventListener('submit',e=>{e.preventDefault();answer(formData(e.target).answer);});if(ex==='count')$('#start-count').onclick=()=>{dealt=0;pace=Number($('#pace').value);$('#start-count').disabled=true;$('#pace').disabled=true;const deal=()=>{if(!alive)return;if(dealt===q.cards.length){clearInterval(timer);$('#count-cards').innerHTML=card(0,0,true);$('#count-position').textContent='Enter your final running count.';$('#answer-form').classList.remove('hidden');$('input',$('#answer-form')).focus();return;}$('#count-cards').innerHTML=card(q.cards[dealt],dealt);$('#count-position').textContent=`Card ${++dealt} of ${q.cards.length}`;};deal();timer=setInterval(deal,pace);};}
async function answer(value){$$('[data-answer],#answer-form button').forEach(b=>b.disabled=true);try{const result=await api('/api/drill/answer','POST',{id:challenge.id,answer:value});if(!alive)return;attempts++;correct+=Number(result.correct);streak=result.correct?streak+1:0;$('#accuracy').textContent=number(correct/attempts*100)+'%';$('#correct-stat').textContent=`${correct} / ${attempts}`;$('#streak').textContent=streak;if($('#points'))$('#points').textContent=correct*10;if($('#checkout-progress'))$('#checkout-progress').style.width=attempts/20*100+'%';$('#drill-feedback').className='feedback '+(result.correct?'positive':'negative');$('#drill-feedback').textContent=result.correct?`Correct · ${result.seconds}s`:`Correct answer: ${{H:'Hit',S:'Stand',D:'Double',P:'Split',R:'Surrender'}[result.answer]||result.answer} · ${result.seconds}s`;if(challenge.exercise==='count')$('#count-cards').innerHTML=`<div class="cards compact">${challenge.cards.map((c,i)=>card(c,i)).join('')}</div>`;$('#next-wrap').innerHTML='<button id="next-exercise" class="primary mt">Next Exercise →</button>';$('#next-exercise').onclick=next;$('#next-exercise').focus();if(mode==='career')await leaderboard();}catch(e){$('#drill-feedback').textContent=e.message;$('#next-wrap').innerHTML='<button id="next-exercise">New Exercise</button>';$('#next-exercise').onclick=next;}}
await next();if(mode==='career')await leaderboard();}

async function chartsPage(){let h17=false,tab='basic';async function paint(){const data=await api('/api/charts?h17='+h17);$('#page').innerHTML=head('Strategy Charts','4–8 decks · US peek · Double after split · No surrender.',`<button id="print-chart">Print Chart</button>`)+`<div class="toolbar"><div class="tabs"><button data-chart="basic" class="${tab==='basic'?'active':''}">Basic Strategy</button><button data-chart="deviation" class="${tab==='deviation'?'active':''}">Hi-Lo Deviations</button></div>${tab==='basic'?`<select id="chart-rule" aria-label="Dealer rule"><option value="false" ${!h17?'selected':''}>S17</option><option value="true" ${h17?'selected':''}>H17</option></select>`:''}</div>${tab==='basic'?`<div class="legend">${[['H','Hit'],['S','Stand'],['D','Double'],['P','Split']].map(([a,l])=>`<span class="badge act-${a}">${a} · ${l}</span>`).join('')}</div><div class="table-wrap"><table class="strategy-table"><thead><tr><th>Player / Dealer</th>${['2','3','4','5','6','7','8','9','10','A'].map(x=>`<th style="text-align:center">${x}</th>`).join('')}</tr></thead><tbody>${data.rows.map((r,i)=>`${[0,16,24].includes(i)?`<tr><td colspan="11" style="text-align:left">${i===0?'Hard totals':i===16?'Soft totals':'Pairs'}</td></tr>`:''}<tr><td>${r.label==='1,1'?'A,A':r.label}</td>${r.actions.map(a=>`<td class="act-${a}">${a}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="notice">If doubling is unavailable, hit except on soft 18 or soft 19, where you stand. A split hand that cannot be split again uses its total-dependent play. These charts do not cover single-deck, double-deck, or no-hole-card games.</div>`:`<div class="notice">Common six-deck S17 Hi-Lo indices, using a floored true count. Take the indexed action at or above the count; below a stand index, hit. Insurance is taken at TC +3 or above. These are not verified against the reference’s private chart tiers.</div><div class="table-wrap"><table><thead><tr><th>Hand</th><th>Dealer</th><th>Index</th><th>At or above index</th></tr></thead><tbody>${data.indices.map(([hand,up,n,a])=>`<tr><td>${hand===20?'10,10':hand}</td><td>${up===1?'A':up}</td><td>${n>=0?'+':''}${n}</td><td>${{H:'Hit',S:'Stand',D:'Double',P:'Split'}[a]}</td></tr>`).join('')}<tr><td>Insurance</td><td>A</td><td>+3</td><td>Take insurance</td></tr></tbody></table></div>`}`;$('#print-chart').onclick=()=>window.print();$$('[data-chart]').forEach(b=>b.onclick=()=>{tab=b.dataset.chart;paint().catch(errorView);});$('#chart-rule')?.addEventListener('change',e=>{h17=e.target.value==='true';paint().catch(errorView);});}await paint();}

async function simulationPage(key){let result=null,running=false,pollTimer=null,alive=true;let initial;try{initial=JSON.parse(localStorage.getItem('simulation-config')||'{}');}catch{initial={};}const defaults={bankroll:60000,unit:10,rph:100,decks:6,penetration:75,h17:false,das:true,surrender:false,rsa:false,payout:1.5,wong:-20,rounds:100000,seed:42,...initial};const spread=initial.spread||Array.from({length:11},(_,i)=>({count:i-3,units:[1,1,1,1,2,4,8,12,16,20,20][i],hands:1}));cleanup=()=>{alive=false;clearTimeout(pollTimer);};$('#page').innerHTML=head(names[key],'Estimate EV and risk from real shuffled shoes, explore variance, and export the results.')+`<form id="sim-form"><div class="sim-layout"><div class="sim-settings"><div class="panel mb"><h3>${icon('wallet')} Bankroll Settings</h3>${field('bankroll','Available bankroll ($)',defaults.bankroll,'number','required min="1" max="1000000000" step=".01"') }<div class="grid two">${field('unit','Unit amount ($)',defaults.unit,'number','required min=".01" max="100000" step=".01"')}${field('rph','Rounds per hour',defaults.rph,'number','required min="1" max="1000"')}</div></div><div class="panel mb"><h3>${icon('cards')} Table Rules</h3><div class="grid two">${select('decks','Decks',[4,6,8],defaults.decks)}${field('penetration','Penetration (%)',defaults.penetration,'number','required min="25" max="90"')}${select('h17','Dealer rule',[['false','S17'],['true','H17']],defaults.h17)}${select('payout','Blackjack payout',[[1.5,'3:2'],[1.2,'6:5']],defaults.payout)}</div>${[['das','Double after split'],['surrender','Late surrender'],['rsa','Resplit aces']].map(([k,l])=>`<label class="check-label field"><input type="checkbox" name="${k}" ${defaults[k]?'checked':''}>${l}</label>`).join('')}${select('wong','Wong in at true count',[[-20,'Always play'],[-1,'−1 or above'],[0,'0 or above'],[1,'+1 or above'],[2,'+2 or above'],[3,'+3 or above']],defaults.wong)}</div><div class="panel mb"><h3>${icon('settings')} Simulation</h3>${select('rounds','Rounds',[[10000,'10,000 · quick check'],[100000,'100,000'],[500000,'500,000'],[1000000,'1,000,000']],defaults.rounds)}${field('seed','Random seed',defaults.seed,'number','required step="1"')}<p class="field-hint">Use the same seed and settings to reproduce a run.</p></div></div><div class="sim-output"><div class="metric-grid" id="sim-metrics">${[['Expected Value','/hour'],['1 Standard Deviation','per √hour'],['Risk of Ruin','approximation'],['Hours to N₀','hours']].map(([l,s])=>`<div class="metric"><span class="label">${l}</span><span class="value">—</span><small>${s}</small></div>`).join('')}</div><div class="panel mt"><h3>Bet Spread</h3><p>Wager in units per hand. Each row applies until the next threshold.</p><div class="table-wrap"><table class="spread-table"><thead><tr><th>True Count</th><th>Units / Hand</th><th>Hands</th></tr></thead><tbody>${spread.map((s,i)=>`<tr><td>${s.count>=0?'+':''}${s.count}<input type="hidden" name="count-${i}" value="${s.count}"></td><td><input aria-label="Units at count ${s.count}" name="units-${i}" type="number" min=".01" max="1000" step=".01" value="${s.units}" required></td><td><select name="hands-${i}" aria-label="Hands at count ${s.count}"><option value="1" ${s.hands===1?'selected':''}>1 hand</option><option value="2" ${s.hands===2?'selected':''}>2 hands</option></select></td></tr>`).join('')}</tbody></table></div><div class="toolbar"><button class="primary" type="submit" id="run-sim">${icon('chart')} Run Simulation</button><span id="sim-status" role="status" class="muted"></span></div><p class="form-error" role="alert"></p></div><div id="sim-result" class="mt"></div><div class="notice">The engine supports basic strategy or six-deck S17 Hi-Lo indices. Both hands share a dealer and shoe; split and double restrictions apply to every hand. Confidence intervals reflect shoe-level sampling variation. Risk of ruin and N₀ use a constant-stakes diffusion approximation; estimates are not guarantees.</div></div></div></form>`;
$('#sim-form').onsubmit=async e=>{e.preventDefault();if(running)return;const data=formData(e.target);const cfg={};for(const k of ['bankroll','unit','rph','decks','penetration','payout','wong','rounds','seed'])cfg[k]=Number(data[k]);cfg.h17=data.h17==='true';cfg.playMode=data.playMode;cfg.maxHands=Number(data.maxHands);cfg.doubleRule=data.doubleRule;cfg.splitAces=data.splitAces==='on';for(const k of ['das','rsa','surrender'])cfg[k]=data[k]==='on';cfg.spread=spread.map((s,i)=>({count:s.count,units:Number(data['units-'+i]),hands:Number(data['hands-'+i])}));if(cfg.playMode==='deviations'&&(cfg.decks!==6||cfg.h17||cfg.surrender)){$('.form-error').textContent='For Hi-Lo indices, choose six decks, S17, and turn off surrender.';return;}localStorage.setItem('simulation-config',JSON.stringify(cfg));running=true;$('#run-sim').disabled=true;$('#sim-status').innerHTML='<span class="spinner"></span> Simulating shuffled shoes…';$('.form-error').textContent='';try{const job=await api('/api/simulate','POST',cfg);const poll=async()=>{if(!alive)return;try{const status=await api('/api/simulate/'+job.id);if(!alive)return;if(status.status==='running'){pollTimer=setTimeout(poll,1200);return;}if(status.status==='error')throw new Error(status.error);result=status.result;showResult();finish();}catch(error){$('.form-error').textContent=error.message;finish();}};pollTimer=setTimeout(poll,500);}catch(error){$('.form-error').textContent=error.message;finish();}};
const simExtra=document.createElement('div');simExtra.innerHTML=select('playMode','Playing strategy',[['basic','Basic strategy'],['deviations','Hi-Lo indices (6D S17)']],defaults.playMode||'basic')+select('maxHands','Split limit per starting hand',[[1,'No splits'],[2,'Up to 2 hands'],[4,'Up to 4 hands']],defaults.maxHands||4)+select('doubleRule','Double rule',[['any','Any first two cards'],['10-11','Totals 10 and 11'],['9-11','Totals 9 through 11']],defaults.doubleRule||'any')+`<label class="check-label field"><input name="splitAces" type="checkbox" ${defaults.splitAces!==false?'checked':''}>Allow splitting aces</label><p class="field-hint">Hi-Lo index play requires six decks, S17, and no surrender. Other settings support basic strategy.</p>`;$('.sim-settings .panel:nth-child(2)').append(simExtra);
function finish(){running=false;$('#run-sim').disabled=false;$('#sim-status').textContent=result?`${number(result.rounds,0)} rounds completed`:'';}
function showResult(){const r=result;$('#sim-metrics').innerHTML=[['Expected Value',money(r.ev),'/hour',r.ev>0?'positive':'negative'],['1 Standard Deviation','± '+money(r.sd),'per √hour',''],['Risk of Ruin',number(r.risk*100,2)+'%','approximation',''],['Hours to N₀',r.n0?number(r.n0,0):'∞',r.n0?'hours':'no positive estimated edge','']].map(([l,v,s,c])=>`<div class="metric"><span class="label">${l}</span><span class="value ${c}">${v}</span><small>${s}</small></div>`).join('');$('#sim-result').innerHTML=`<div class="panel"><div class="flex between"><h3>Simulated Profit Path</h3><button type="button" id="export-sim" class="small">${icon('download')} Export</button></div>${chart([r.trajectory],{labels:['Profit path']})}<div class="notice">95% confidence interval for hourly EV: <strong>${money(r.ci[0])} to ${money(r.ci[1])}</strong>. ${r.ci[0]<=0&&r.ci[1]>=0?'This run does not establish a positive or negative edge with 95% confidence.':''}</div><div class="table-wrap"><table><tbody>${[['Observed rounds',number(r.rounds,0)],['Played rounds',number(r.played,0)],['Shuffled shoes',number(r.shoes,0)],['Net profit',money(r.profit)],['Average total wager / played round',money(r.averageBet)],['Return / total wager',number(r.edge*100,3)+'%'],['Winning / losing / pushed rounds',`${r.wins} / ${r.losses} / ${r.pushes}`],['Seed',r.seed]].map(([l,v])=>`<tr><td>${l}</td><td>${v}</td></tr>`).join('')}</tbody></table></div></div>`;$('#export-sim').onclick=()=>download('simulation.json',JSON.stringify({settings:JSON.parse(localStorage.getItem('simulation-config')),result:r},null,2),'application/json');}
}

async function forumPage(){const threads=await records('thread');const id=new URLSearchParams(location.search).get('thread');if(id){const thread=threads.find(t=>t.id===id);if(!thread){$('#page').innerHTML=empty('Thread not found','It may have been removed.',link('forum','Back to Forum','button'));return;}const replies=await records('reply',id);$('#page').innerHTML=head(esc(thread.body.title),`${esc(thread.body.category)} · Started by ${esc(thread.username)}`,link('forum','← All Discussions','button'))+`<article class="panel mb"><div class="flex mb"><span class="avatar">${esc(thread.username[0])}</span><strong>${esc(thread.username)}</strong><span class="muted">${new Date(thread.created*1000).toLocaleDateString()}</span></div><div class="post">${esc(thread.body.text)}</div>${thread.owner===user.id?'<button class="ghost small mt" id="edit-thread">Edit Thread</button>':''}</article><h3>${replies.length} Replies</h3>${replies.slice().reverse().map(r=>`<article class="panel mb"><div class="flex mb"><span class="avatar">${esc(r.username[0])}</span><strong>${esc(r.username)}</strong><small class="muted">${new Date(r.created*1000).toLocaleString()}</small></div><div class="post">${esc(r.body.text)}</div>${r.owner===user.id?`<button class="ghost small mt" data-edit-reply="${r.id}">Edit Reply</button>`:''}</article>`).join('')}<form id="reply-form" class="panel"><h3>Join the Discussion</h3>${textarea('text','Your reply','','required maxlength="10000"')}<p class="form-error" role="alert"></p><button class="primary">Post Reply</button></form>`;$('#reply-form').onsubmit=async e=>{e.preventDefault();try{await saveRecord('reply',formData(e.target),id);await forumPage();toast('Reply posted.');}catch(error){$('.form-error').textContent=error.message;}};$('#edit-thread')?.addEventListener('click',()=>editThread(thread));$$('[data-edit-reply]').forEach(b=>b.onclick=()=>{const r=replies.find(x=>x.id===b.dataset.editReply);modal('Edit Reply',textarea('text','Reply',r.body.text,'required maxlength="10000"'),async data=>{await saveRecord('reply',data,id,r.id);await forumPage();});});return;}
let category='All',search='';function paint(){const filtered=threads.filter(t=>(category==='All'||t.body.category===category)&&(`${t.body.title} ${t.body.text}`.toLowerCase().includes(search.toLowerCase())));$('#page').innerHTML=head('Private Forum','Strategy, trip reports, and conversations with the community.',button(icon('plus')+' New Discussion','new-thread'))+`<div class="toolbar"><input id="forum-search" type="search" placeholder="Search discussions…" aria-label="Search discussions" value="${esc(search)}"><select id="forum-category" aria-label="Category">${['All','Strategy','Trip Reports','Team Formation','General'].map(c=>`<option ${c===category?'selected':''}>${c}</option>`).join('')}</select></div><div class="panel" style="padding:0">${filtered.length?filtered.map(t=>`<a class="thread-item" href="${paths.forum}?thread=${t.id}"><span class="badge">${esc(t.body.category)}</span><h3>${esc(t.body.title)}</h3><small class="muted">${esc(t.username)} · ${new Date(t.created*1000).toLocaleDateString()}</small></a>`).join(''):empty('Start the Conversation','No discussions match this view. Create a thread to share a question or observation.')}</div>`;$('#new-thread').onclick=()=>editThread();$('#forum-category').onchange=e=>{category=e.target.value;paint();};$('#forum-search').onchange=e=>{search=e.target.value;paint();};}function editThread(row){const b=row?.body||{};modal(row?'Edit Discussion':'New Discussion',field('title','Title',b.title,'text','required maxlength="150"')+select('category','Category',['Strategy','Trip Reports','Team Formation','General'],b.category||'General')+textarea('text','Message',b.text,'required maxlength="20000"'),async data=>{const saved=await saveRecord('thread',data,null,row?.id);go(paths.forum+'?thread='+saved.record.id);toast('Discussion saved.');});}paint();}

async function messagesPage(){const result=await api('/api/messages');let selected=new URLSearchParams(location.search).get('to')||'';const namesList=[...new Set(result.messages.map(m=>m.sender===user.id?m.recipient_name:m.sender_name))];if(!selected)selected=namesList[0]||'';$('#page').innerHTML=head('Messages','Private conversations between you and another registered player.')+`<div class="panel"><div class="toolbar"><select id="conversation" aria-label="Conversation"><option value="">New conversation</option>${namesList.map(n=>`<option ${n===selected?'selected':''}>${esc(n)}</option>`).join('')}</select><button id="new-message">New Message</button></div><div class="message-list">${result.messages.filter(m=>m.sender_name===selected||m.recipient_name===selected).map(m=>`<div class="message ${m.sender===user.id?'mine':''}"><small>${esc(m.sender_name)} · ${new Date(m.created*1000).toLocaleString()}</small><p>${esc(m.body)}</p></div>`).join('')||empty('No Messages Yet','Use an existing player’s username to start a conversation.')}</div><form id="message-form" class="mt">${field('recipient','Recipient username',selected,'text','required maxlength="30"')}${textarea('text','Message','','required maxlength="10000"')}<p class="form-error" role="alert"></p><button class="primary">Send Message ${icon('arrow')}</button></form></div>`;$('#conversation').onchange=e=>go(paths.messages+'?to='+encodeURIComponent(e.target.value));$('#new-message').onclick=()=>{$('#recipient').value='';$('#recipient').focus();};$('#message-form').onsubmit=async e=>{e.preventDefault();const b=$('button',e.target);b.disabled=true;try{const d=formData(e.target);await api('/api/messages','POST',d);go(paths.messages+'?to='+encodeURIComponent(d.recipient));toast('Message sent.');}catch(error){$('.form-error').textContent=error.message;b.disabled=false;}};$('.message-list').scrollTop=$('.message-list').scrollHeight;}

async function directoryPage(){let casinos=await records('casino'),search='',heat='All',view='list';const id=new URLSearchParams(location.search).get('casino');if(id){const casino=casinos.find(c=>c.id===id);if(!casino){$('#page').innerHTML=empty('Game not found','This entry may have been removed.',link('directory','Back to Directory','button'));return;}const b=casino.body,reviews=await records('review',id);$('#page').innerHTML=head(esc(b.name),esc(b.city),link('directory','← Directory','button'))+`<div class="grid two"><div class="panel"><h3>Game Conditions</h3><div class="post">${esc(b.rules)}</div><div class="statline mt"><div><small class="muted">PENETRATION</small><strong>${b.penetration}%</strong></div><div><small class="muted">MINIMUM BET</small><strong>${money(b.minBet)}</strong></div><div><small class="muted">HEAT</small><strong>${esc(b.heat)}</strong></div></div><p class="mt post">${esc(b.notes)}</p><small class="muted">Reported by ${esc(casino.username)} · ${new Date(casino.updated*1000).toLocaleDateString()}</small>${casino.owner===user.id?'<div class="mt"><button id="edit-casino">Edit Entry</button></div>':''}</div><div class="panel"><h3>Community Reviews</h3>${reviews.map(r=>`<div class="mb"><strong>${esc(r.username)} · ${r.body.rating}/5</strong><p class="post">${esc(r.body.text)}</p></div>`).join('')||'<p>No reviews yet.</p>'}<button id="new-review" class="primary">Write Review</button></div></div><div class="notice">Conditions are submitted by players and can change. The report date and author are shown above.</div>`;$('#edit-casino')?.addEventListener('click',()=>edit(casino));$('#new-review').onclick=()=>modal('Write Review',select('rating','Rating',[1,2,3,4,5],5)+textarea('text','Your experience','','required maxlength="4000"'),async data=>{await saveRecord('review',data,id);await directoryPage();toast('Review saved.');});return;}
function paint(){const rows=casinos.filter(c=>`${c.body.name} ${c.body.city}`.toLowerCase().includes(search.toLowerCase())&&(heat==='All'||c.body.heat===heat));$('#page').innerHTML=head('Game Directory','Player-submitted game conditions, reports, and reviews.',button(icon('plus')+' Add Game','new-casino'))+`<div class="toolbar"><input id="directory-search" type="search" placeholder="Search casino or city…" value="${esc(search)}" aria-label="Search directory"><select id="heat-filter" aria-label="Heat level">${['All','Low','Moderate','High','Unknown'].map(h=>`<option ${h===heat?'selected':''}>${h}</option>`).join('')}</select><div class="spacer"></div><div class="tabs"><button data-view="list" class="${view==='list'?'active':''}">List</button><button data-view="map" class="${view==='map'?'active':''}">Map</button></div></div>${view==='map'?`<div class="map" role="region" aria-label="World coordinate map"><svg viewBox="0 0 720 360" preserveAspectRatio="none" aria-hidden="true">${Array.from({length:13},(_,i)=>`<path d="M${i*60} 0v360" stroke="#4c7286"/>`).join('')}${Array.from({length:7},(_,i)=>`<path d="M0 ${i*60}h720" stroke="#4c7286"/>`).join('')}<path d="M50 50l90-25 65 40-30 55-40 20 35 40-10 55-25 70-22-36-2-65-36-35-25-70ZM305 65l50-32 60 20 70-15 150 50-30 60-65-20-30 40-60-55-45 7 10 45-50 100-40-20-35-90 15-40ZM555 245l55-15 45 35-20 35-65-7Z" fill="#49706d"/></svg>${rows.map((c,i)=>`<button class="map-marker" data-marker="${c.id}" style="left:${(c.body.lng+180)/360*100}%;top:${(90-c.body.lat)/180*100}%" aria-label="${esc(c.body.name)}">${i+1}</button>`).join('')}</div><p class="field-hint">Schematic equirectangular world map. Marker positions use submitted latitude and longitude; land outlines are illustrative.</p>`:''}<div class="grid two mt">${rows.map(c=>`<a href="${paths.directory}?casino=${c.id}" class="panel"><div class="flex between"><h3>${esc(c.body.name)}</h3><span class="badge">${esc(c.body.heat)} heat</span></div><p>${esc(c.body.city)}</p><p>${esc(c.body.rules).slice(0,180)}</p><div class="flex between"><small class="muted">${c.body.penetration}% penetration · ${money(c.body.minBet)} min</small><small class="muted">${new Date(c.updated*1000).toLocaleDateString()}</small></div></a>`).join('')}</div>${!rows.length?`<div class="panel mt">${empty('No Game Reports Yet','Add a casino you know. This directory starts empty so every entry has a real contributor.')}</div>`:''}`;$('#new-casino').onclick=()=>edit();$('#directory-search').onchange=e=>{search=e.target.value;paint();};$('#heat-filter').onchange=e=>{heat=e.target.value;paint();};$$('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;paint();});$$('[data-marker]').forEach(b=>b.onclick=()=>go(paths.directory+'?casino='+b.dataset.marker));}
function edit(row){const b=row?.body||{};modal(row?'Edit Game':'Add Game',field('name','Casino / game name',b.name,'text','required maxlength="120"')+field('city','City and country',b.city,'text','required maxlength="120"')+textarea('rules','Game rules',b.rules,'required maxlength="2000" placeholder="Decks, H17/S17, payout, surrender, DAS…"')+`<div class="grid two">${select('heat','Reported heat',['Unknown','Low','Moderate','High'],b.heat||'Unknown')}${field('penetration','Penetration (%)',b.penetration??75,'number','required min="0" max="100"')}${field('minBet','Minimum bet (USD)',b.minBet??25,'number','required min="0" step=".01"')}${field('lat','Latitude',b.lat??'','number','required min="-90" max="90" step="any"')}${field('lng','Longitude',b.lng??'','number','required min="-180" max="180" step="any"')}</div>`+textarea('notes','Notes',b.notes,'maxlength="4000"'),async data=>{await saveRecord('casino',data,null,row?.id);await directoryPage();toast('Game report saved.');});}paint();}

function tutorialPage(){const lessons=[['Start with the rules','Blackjack compares your hand with the dealer’s. Number cards use their face value; J, Q, and K count as 10. An ace counts as 1 or 11. A hand above 21 busts. A two-card ace plus a ten-value card is a natural blackjack.','Which hand is a natural blackjack?',['A + K','7 + 7 + 7','10 + 9'],0],['Choose your action','Hit takes another card. Stand ends your turn. Double adds an equal wager and takes exactly one more card. Split separates a pair into two hands with an additional wager. The best decision depends on your total, the dealer’s upcard, and the rules.','What happens after doubling?',['You may keep hitting','You receive exactly one more card','You split your hand'],1],['Learn Hi-Lo','Start at zero after a shuffle. Add +1 for each 2, 3, 4, 5, or 6. Add 0 for 7, 8, or 9. Subtract 1 for each ten, face card, or ace. This total is the running count.','What is the count of 2, K, 6, 8?',['−1','0','+1'],2],['Convert to a true count','Divide the running count by the number of decks remaining. This application rounds down toward negative infinity. For example, +9 with 3 decks left is +3; −3 with 2 decks left becomes −2.','Running count +12, four decks remaining:',['+3','+4','+8'],0],['Understand variance','A positive long-run expectation does not promise a profit in a session. Results fluctuate, sometimes substantially. Simulations estimate outcomes under a particular model and have sampling uncertainty. Use confidence intervals when interpreting estimated EV.','What does positive expected value mean?',['Every session wins','A positive average under the modeled assumptions','There is no risk of loss'],1],['Build a practice routine','Start with basic strategy, then practice running counts and true counts. Add deck estimation and deviations after the foundations are consistent. Use checkouts to identify weak areas and log your results over time.','Which skill should you establish first?',['Large bet spreads','Basic strategy','Fast casino play'],1]];let step=Math.min(Number(localStorage.getItem('tutorial-step')||0),lessons.length-1);function paint(){const [title,body,q,answers,correct]=lessons[step];$('#page').innerHTML=head('Interactive Tutorial','A guided introduction to the tools and training.')+`<div class="tutorial-step"><div class="flex between"><span class="badge">Lesson ${step+1} of ${lessons.length}</span><span class="muted">${Math.round(step/lessons.length*100)}% complete</span></div><div class="progress-track"><div style="width:${step/lessons.length*100}%"></div></div><div class="panel mt"><h2>${title}</h2><p style="font-size:17px">${body}</p><h3 class="mt">${q}</h3><div class="grid">${answers.map((a,i)=>`<button data-quiz="${i}" style="justify-content:flex-start">${a}</button>`).join('')}</div><p id="quiz-feedback" class="feedback" aria-live="polite"></p><div class="toolbar"><button id="previous-lesson" ${step===0?'disabled':''}>← Previous</button><div class="spacer"></div><button class="primary" id="next-lesson" disabled>${step===lessons.length-1?'Start Training':'Next Lesson →'}</button></div></div></div>`;$$('[data-quiz]').forEach(b=>b.onclick=()=>{const ok=Number(b.dataset.quiz)===correct;$('#quiz-feedback').textContent=ok?'Correct. You’re ready to continue.':'Try again. Review the lesson above.';$('#quiz-feedback').className='feedback '+(ok?'positive':'negative');$('#next-lesson').disabled=!ok;});$('#previous-lesson').onclick=()=>{step--;localStorage.setItem('tutorial-step',step);paint();};$('#next-lesson').onclick=()=>{if(step===lessons.length-1){localStorage.setItem('tutorial-complete','true');go(paths.basic);}else{step++;localStorage.setItem('tutorial-step',step);paint();}};}paint();}

async function settingsPage(){const progress=await api('/api/progress');$('#page').innerHTML=head('Account Settings','Manage your profile and review your training progress.')+`<div class="grid two"><form class="panel" id="profile-form"><h3>Profile</h3>${field('username','Username',user.username,'text','required minlength="3" maxlength="30"')}${field('email','Email address',user.email,'email','disabled')}<p class="form-error" role="alert"></p><button class="primary">Save Profile</button><div class="notice">Every feature is included. Your account never expires because of a trial or subscription.</div>${configInfo.recoveryConfigured?'<a href="/auth/forgot-password">Reset password by email →</a>':'<p class="field-hint">Email recovery is not enabled for this local preview. You can change your password below.</p>'}</form><div class="panel"><h3>Training Progress</h3>${progress.progress.length?`<div class="table-wrap"><table><thead><tr><th>Drill</th><th>Correct</th><th>Accuracy</th></tr></thead><tbody>${progress.progress.map(p=>`<tr><td>${names[p.mode]}</td><td>${p.correct} / ${p.attempts}</td><td>${number(p.correct/p.attempts*100)}%</td></tr>`).join('')}</tbody></table></div>`:empty('Ready When You Are','Complete your first drill to start recording progress.',link('basic','Start Training','button primary'))}</div></div>`;passwordSettings();$('#profile-form').onsubmit=async e=>{e.preventDefault();try{const result=await api('/api/profile','PATCH',formData(e.target));user=result.user;toast('Profile saved.');render();}catch(error){$('.form-error').textContent=error.message;}};}

function passwordSettings(){
 const panel=document.createElement('form');panel.id='password-form';panel.className='panel mt';
 panel.innerHTML=`<h3>Change password</h3><div class="grid three">${field('current','Current password','','password','required autocomplete="current-password"')}${field('new-password','New password','','password','required minlength="10" maxlength="256" autocomplete="new-password"')}${field('confirm-password','Confirm new password','','password','required minlength="10" autocomplete="new-password"')}</div><p class="field-hint">Changing your password signs out your other sessions.</p><p class="form-error" role="alert"></p><button class="primary">Update Password</button>`;
 $('#page').append(panel);panel.onsubmit=async e=>{e.preventDefault();const d=formData(panel);const error=$('.form-error',panel);error.textContent='';if(d['new-password']!==d['confirm-password']){error.textContent='Passwords do not match.';return;}const b=$('button',panel);b.disabled=true;try{await api('/api/change-password','POST',{current:d.current,password:d['new-password']});panel.reset();toast('Password updated. Other sessions signed out.');}catch(e){error.textContent=e.message;}finally{b.disabled=false;}};
}

function legalPage(kind){const pages={about:{title:'A Free Toolkit for Players',intro:'Felt & Fortune brings free blackjack training, simulation, and results tracking together in one place.',sections:[['The project','Practice blackjack decisions, run configurable simulations, track your results, and collaborate with other players. Accounts are free and no payment method is collected.'],['Independent implementation','Felt & Fortune is an independent student project. AP Toolbox and Blackjack.tools inform the feature research. All training logic, calculations, and community features here use our own implementation.'],['Transparent results','The directory and forum begin empty. Users supply their own observations. Calculator results come from the selected simulation settings, and estimates display their uncertainty.']]},privacy:{title:'Privacy Policy',intro:'This notice describes the local application’s implemented data handling. The site operator must add their contact information and review this policy before public launch.',sections:[['Account data','The application stores your username, email address, and a salted scrypt password hash. It uses an HttpOnly session cookie to keep you signed in. Passwords are never stored in plaintext.'],['Your records','Personal bankrolls and their sessions are restricted to you. Shared bankroll members can view their shared records. Editors may add and edit their own sessions; owners manage the bankroll and membership.'],['Community and messages','Forum posts, directory entries, reviews, and career leaderboard usernames are visible to other signed-in users. Private messages are available to their sender and recipient. The server operator can access its database and should protect backups.'],['External content','The homepage uses artwork bundled with this application. This application includes no advertising or analytics trackers.'],['Retention and requests','Records remain in the application database until removed. Sessions expire after 14 days; reset links expire after 30 minutes. Before public launch, the operator must publish a contact method for access, correction, export, and deletion requests.']]},terms:{title:'Terms of Use',intro:'These are provisional terms for this independently developed free application. The operator must review and finalize them, including operator identity and jurisdiction, before public launch.',sections:[['Free access','All implemented features are free to end users. There are no subscription plans, trial expiration dates, or payment requirements.'],['Your account','Keep your credentials private and submit only information you are authorized to share. Do not impersonate other users, abuse community features, or attempt to access other users’ private records.'],['Training and simulations','Exercises and simulations are educational tools. Results depend on the documented rules and assumptions. Simulated EV is an estimate, not a promise of financial results. This application does not accept wagers or execute gambling transactions.'],['User contributions','You retain responsibility for your posts, messages, reviews, and game reports. Do not submit private third-party information or present fabricated reports as real observations.'],['Independent project','Felt & Fortune is an independent educational project. The operator will finalize these terms and contact details before public launch.']]}};const p=pages[kind];$('#app').innerHTML=navbar()+`<main id="main" class="legal-page"><a href="/">← Back to Home</a><h1 class="mt">${p.title}</h1><p>${p.intro}</p>${p.sections.map(([t,b])=>`<h2>${t}</h2><p>${b}</p>`).join('')}${kind==='about'?'<a class="button primary mt" href="/auth/signup">Create a Free Account →</a>':''}</main>`+footer();}

function go(url){history.pushState({},'',url);render();}
document.addEventListener('click',e=>{const a=e.target.closest('a');if(!a||e.ctrlKey||e.metaKey||e.shiftKey||e.altKey||a.target||a.download)return;const url=new URL(a.href,location.href);if(url.origin!==location.origin)return;e.preventDefault();if(url.pathname===location.pathname&&url.search===location.search&&url.hash){history.pushState({},'',url);document.getElementById(decodeURIComponent(url.hash.slice(1)))?.scrollIntoView({behavior:'smooth'});$('.navlinks')?.classList.remove('open');$('#nav-menu')?.setAttribute('aria-expanded','false');return;}go(url.pathname+url.search+url.hash);});
window.addEventListener('popstate',()=>render());
async function render(){const version=++routeVersion;requestController.abort();requestController=new AbortController();cleanup();cleanupNav();cleanup=()=>{};cleanupNav=()=>{};if($('#modal').open)$('#modal').close();const path=location.pathname.replace(/\/$/,'')||'/';window.scrollTo(0,0);if(path==='/'){homepage();if(location.hash)setTimeout(()=>document.getElementById(decodeURIComponent(location.hash.slice(1)))?.scrollIntoView(),50);return;}if(['/about','/privacy','/terms'].includes(path)){legalPage(path.slice(1));return;}if(path.startsWith('/auth/')){const mode=path.split('/')[2];if(['signup','login','forgot-password','reset-password'].includes(mode)){authPage(mode);return;}}if(path==='/dashboard/ev-calculator'){history.replaceState({},'',paths.simulate);render();return;}const key=Object.keys(paths).find(k=>paths[k]===path);if(!key){$('#app').innerHTML=navbar()+`<main class="legal-page" id="main">${empty('Page Not Found','Choose a page from the toolbox.',link('dashboard','Open Dashboard','button primary'))}</main>`;return;}if(!user){sessionStorage.setItem('after-login',path);history.replaceState({},'','/auth/login');authPage('login');return;}shell(key);try{if(['dashboard','results'].includes(key))await resultsPage(key);else if(key==='bankrolls')await bankrollPage();else if(key==='simulate')await simulationPage(key);else if(['basic','count','deviation','decks','true-count','checkout','career'].includes(key))await drillPage(key);else if(key==='charts')await chartsPage();else if(key==='tutorial')tutorialPage();else if(key==='forum')await forumPage();else if(key==='messages')await messagesPage();else if(key==='directory')await directoryPage();else if(key==='settings')await settingsPage();}catch(error){if(version===routeVersion&&$('#page'))errorView(error);}}
async function boot(){try{configInfo=await api('/api/me');user=configInfo.user;}catch(error){toast('The server could not be reached. Reload to try again.');}await render();}
boot();
